<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {formatBytes} from './format-bytes';
import {historyUTC,historyTimeText} from './cloud-history-types';
import {changeKinds,changesURL,parseChangePage,type ChangePage,type ChangeFilters,type RefreshChange} from './refresh-change-types';
const props=defineProps<{run:string;event:string;disabled:boolean}>(),emit=defineEmits<{authenticationRequired:[];close:[]}>();
const opened=ref(false),loading=ref(false),exporting=ref(false),fresh=ref(false),error=ref(''),notice=ref(''),observed=ref(''),value=ref<ChangePage|null>(null),draft=ref<ChangeFilters>({kind:'',query:''}),applied=ref<ChangeFilters>({kind:'',query:''}),before=ref('0'),stack=ref<string[]>([]);
let active=true,generation=0,controller:AbortController|undefined;
const current=(n:number)=>active&&opened.value&&!props.disabled&&n===generation;
function remoteTime(value:string){if(value==='0')return '未提供（原始秒值0）';const n=BigInt(value);return n < -8640000000000n||n>8640000000000n?'超出日期显示范围（原始秒值'+value+'）':new Date(Number(n)*1000).toISOString()+'（原始秒值'+value+'）';}
function differences(row:RefreshChange){if(!row.old||!row.new)return '';return [[row.old.provider_mtime!==row.new.provider_mtime,'修改时间变化'],[row.old.content_md5!==row.new.content_md5,'MD5记录变化'],[row.old.content_sha256!==row.new.content_sha256,'SHA256记录变化']].filter(([changed])=>changed).map(([,label])=>label).join(' · ');}
function close(){generation++;controller?.abort();opened.value=false;loading.value=false;exporting.value=false;fresh.value=false;}
function requestClose(){close();emit('close');}
async function load(cursor:string,filters:ChangeFilters,nextStack:string[]){
 if(!active||!opened.value||props.disabled||loading.value||exporting.value)return;
 const request=++generation,run=props.run,event=props.event;controller?.abort();controller=new AbortController();loading.value=true;fresh.value=false;notice.value='';
 try{const response=await fetch(changesURL(run,event,filters,cursor),{credentials:'same-origin',signal:controller.signal});if(!current(request))return;if(response.status===401){close();emit('authenticationRequired');return}if(!response.ok)throw Error(response.status===404?'未找到该事件的变更证据。':'明细读取失败，请重新核对。');const data=await response.json();if(!current(request))return;const page=parseChangePage(data,run,event,filters,cursor);value.value=page;applied.value={...filters};before.value=cursor;stack.value=nextStack;error.value='';fresh.value=true;observed.value=new Date().toISOString();}
 catch(e:any){if(current(request))error.value=e.message||'明细读取失败。';}finally{if(current(request))loading.value=false;}
}
function apply(){const filters={kind:draft.value.kind,query:draft.value.query.trim()};if(Array.from(filters.query).length>128){error.value='关键词最多128个字符。';fresh.value=false;return}load('0',filters,[]);}
async function download(){
 if(!active||props.disabled||!opened.value||loading.value||exporting.value||!fresh.value)return;
 const request=++generation,run=props.run,event=props.event,filters={...applied.value};controller=new AbortController();exporting.value=true;notice.value='';
 try{const response=await fetch(changesURL(run,event,filters,'0',true),{credentials:'same-origin',signal:controller.signal});if(!current(request))return;if(response.status===401){close();emit('authenticationRequired');return}const raw=await response.text();if(!current(request))return;if(!response.ok)throw Error(response.status===413?'明细超过5000条，未生成部分文件。':'导出失败，未生成文件。');const data=JSON.parse(raw);const page=parseChangePage(data,run,event,filters,'0',5000);if(!historyUTC(data.exported_at_utc)||page.more||BigInt(page.changes.length)!==BigInt(page.matched))throw Error('导出范围或完整性无效，未生成文件。');
  // Validate scope only; save the received bytes without serializing int64 evidence again.
  const link=document.createElement('a'),url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));link.href=url;link.download='cloud-refresh-changes-'+run+'-'+event+'.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='已请求下载当前筛选的完整明细。';
 }catch(e:any){if(current(request))notice.value=e.message||'导出失败。';}finally{if(current(request))exporting.value=false;}
}
function stop(){active=false;close();}
function restore(event:PageTransitionEvent){if(event.persisted)active=true;}
watch(()=>[props.run,props.event,props.disabled],()=>{close();value.value=null;applied.value={kind:'',query:''};draft.value={kind:'',query:''};error.value='';},{flush:'sync'});
onMounted(()=>{opened.value=true;load('0',{...applied.value},[]);window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore)});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore)});
</script>
<template><section class="refresh-change-workspace"><button class="button secondary compact" data-testid="refresh-changes-close" @click="requestClose">关闭此事件明细</button><div v-if="opened" data-testid="refresh-changes-panel"><p class="muted">固定事件 {{event}} 的历史直接子项变化，非当前线上事实；查看不会扫描或修改网盘。</p><form data-testid="refresh-changes-filter" class="change-filters" @submit.prevent="apply"><label>变化类型<select v-model="draft.kind" :disabled="loading||exporting"><option value="">全部类型</option><option v-for="(label,kind) in changeKinds" :value="kind">{{label}}</option></select></label><label>路径、名称或文件ID<input v-model="draft.query" data-testid="refresh-changes-query" :disabled="exporting"/></label><button class="button secondary compact" :disabled="loading||exporting">筛选</button></form><p data-testid="refresh-changes-applied">已显示条件：{{changeKinds[applied.kind]||'全部类型'}} · {{applied.query||'关键词不限'}}</p><p v-if="loading" role="status">正在读取明细…</p><p v-if="error" class="notice danger" role="alert">{{error}}</p><p v-if="value&&!fresh" class="notice">下方保留上次已显示条件的历史结果，分页与导出暂不可用。</p><div class="toolbar"><button class="button secondary compact" data-testid="refresh-changes-reload" :disabled="loading||exporting" @click="load('0',{...applied},[])">重新读取已显示条件</button><button class="button secondary compact" data-testid="refresh-changes-export" :disabled="loading||exporting||!fresh" @click="download">{{exporting?'正在导出…':'导出已显示筛选明细'}}</button></div><p v-if="notice" role="status">{{notice}}</p><template v-if="value"><p>事件全部 {{value.counts.total}} 项 · 新增 {{value.counts.added}} · 删除 {{value.counts.removed}} · 元数据 {{value.counts.metadata_changed}} · 身份 {{value.counts.identity_changed}}；筛选命中 {{value.matched}} 项</p><div class="event-table-scroll"><table data-testid="refresh-changes-table"><thead><tr><th>变化 / 序号</th><th>刷新前</th><th>刷新后</th><th>时间证据 UTC</th></tr></thead><tbody><tr v-for="row in value.changes" :key="row.sequence"><td>{{changeKinds[row.kind]}}<small v-if="differences(row)" class="cell-sub">{{differences(row)}}</small><small class="cell-sub">{{row.sequence}}</small></td><td v-for="side in ['old','new'] as const"><template v-if="row[side]"><strong>{{row[side]!.name}}</strong><small class="cell-sub">{{row[side]!.path}}</small><small class="cell-sub">ID {{row[side]!.fs_id}} · {{row[side]!.directory?'文件夹':formatBytes(row[side]!.size)}}</small><small class="cell-sub">列表观察 {{historyTimeText(row[side]!.observed_at_utc)}}</small><small class="cell-sub">远端修改 UTC {{remoteTime(row[side]!.provider_mtime)}}</small><details><summary>元数据和内容摘要</summary><small class="cell-sub">MD5 {{row[side]!.content_md5||'未记录'}}</small><small class="cell-sub">SHA256 {{row[side]!.content_sha256||'未记录'}}</small><small class="cell-sub">SHA256校验 UTC {{historyTimeText(row[side]!.content_sha256_verified_at_utc||null)}}</small><small class="cell-sub">历史缓存摘要，不据此证明当前远端内容或执行删除。</small></details></template><span v-else>该侧无项目</span></td><td>本机记录 {{row.recorded_at_utc}}<small class="cell-sub">云端列表观察 {{row.cloud_observed_at_utc}}</small></td></tr><tr v-if="!value.changes.length"><td colspan="4">此已显示条件没有明细；不代表远端没有内容。</td></tr></tbody></table></div><div class="toolbar"><button class="button secondary compact" :disabled="loading||exporting||!fresh||!stack.length" @click="load(stack.at(-1)!,{...applied},stack.slice(0,-1))">上一页明细</button><button class="button secondary compact" data-testid="refresh-changes-next" :disabled="loading||exporting||!fresh||!value.more" @click="load(value.next,{...applied},[...stack,before])">更早明细</button></div></template><p v-if="observed" class="muted">本页读取 UTC：{{observed}}；仅对应已显示条件。导出最多5000项，超限不生成部分文件。</p></div></section></template>
<style scoped>
.refresh-change-workspace{margin-top:10px;min-width:0}.refresh-change-workspace>div{margin-top:10px;border-top:1px solid #dce3ed;padding-top:10px}.change-filters{display:flex;gap:8px;flex-wrap:wrap;align-items:end}.change-filters label{display:grid;gap:5px;min-width:0}.change-filters input,.change-filters select{max-width:100%;padding:7px;border:1px solid #cbd5e5;border-radius:5px}.refresh-change-workspace table{min-width:660px}.refresh-change-workspace td{white-space:normal;overflow-wrap:anywhere;vertical-align:top}.refresh-change-workspace .toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.refresh-change-workspace p{font-size:12px;overflow-wrap:anywhere}
</style>
